func (r *InterfaceResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	var plan InterfaceModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	if resp.Diagnostics.HasError() {
		return
	}
	body := interfaceToCreate(ctx, &plan, r.cf, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	obj, res, err := r.client.DcimAPI.DcimInterfacesCreate(ctx).WritableInterfaceRequest(*body).Execute()
	if err != nil {
		resp.Diagnostics.AddError("Error creating netbox_interface", netbox.WrapError(err, res).Error())
		return
	}

	var state InterfaceModel
	interfaceFromAPI(ctx, obj, &plan, &state, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	resp.Diagnostics.Append(resp.State.Set(ctx, &state)...)
	provider.SetIdentityID(ctx, resp.Identity, state.Id, &resp.Diagnostics)
}

func (r *InterfaceResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
	var state InterfaceModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	id, err := netbox.Int32ID(state.Id.ValueInt64())
	if err != nil {
		resp.Diagnostics.AddError("Invalid ID", err.Error())
		return
	}
	obj, res, err := r.client.DcimAPI.DcimInterfacesRetrieve(ctx, id).Execute()
	if err != nil {
		if werr := netbox.WrapError(err, res); netbox.IsNotFound(werr) {
			resp.State.RemoveResource(ctx)
			return
		} else {
			resp.Diagnostics.AddError("Error reading netbox_interface", werr.Error())
			return
		}
	}
	prior := state
	interfaceFromAPI(ctx, obj, &prior, &state, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	resp.Diagnostics.Append(resp.State.Set(ctx, &state)...)
	provider.SetIdentityID(ctx, resp.Identity, state.Id, &resp.Diagnostics)
}

func (r *InterfaceResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var plan, state InterfaceModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	id, err := netbox.Int32ID(state.Id.ValueInt64())
	if err != nil {
		resp.Diagnostics.AddError("Invalid ID", err.Error())
		return
	}
	body := interfaceToPatch(ctx, &plan, &state, r.cf, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	obj, res, err := r.client.DcimAPI.DcimInterfacesPartialUpdate(ctx, id).PatchedWritableInterfaceRequest(*body).Execute()
	if err != nil {
		resp.Diagnostics.AddError("Error updating netbox_interface", netbox.WrapError(err, res).Error())
		return
	}

	var out InterfaceModel
	interfaceFromAPI(ctx, obj, &plan, &out, &resp.Diagnostics)
	if resp.Diagnostics.HasError() {
		return
	}
	resp.Diagnostics.Append(resp.State.Set(ctx, &out)...)
	provider.SetIdentityID(ctx, resp.Identity, out.Id, &resp.Diagnostics)
}

func (r *InterfaceResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	var state InterfaceModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	id, err := netbox.Int32ID(state.Id.ValueInt64())
	if err != nil {
		resp.Diagnostics.AddError("Invalid ID", err.Error())
		return
	}
	res, err := r.client.DcimAPI.DcimInterfacesDestroy(ctx, id).Execute()
	if err != nil {
		if werr := netbox.WrapError(err, res); !netbox.IsNotFound(werr) {
			resp.Diagnostics.AddError("Error deleting netbox_interface", werr.Error())
		}
	}
}

func (r *InterfaceResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	provider.ImportInt64ID(ctx, req, resp)
}

